<main class="content"><header class="topbar"><div><span class="eyebrow">Campeonato</span><h1><?=View::e($tournament['name'])?></h1></div><a class="button" href="/admin/tournaments">Voltar</a></header><section class="panel"><h2>Identidade visual</h2><form method="post" action="/admin/tournaments/<?=$tournament['id']?>/assets" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><div class="form-grid"><label>Tipo<select name="asset_type"><option value="logo_light">Logo claro</option><option value="logo_dark">Logo escuro</option><option value="favicon">Favicon</option><option value="banner">Banner principal</option><option value="share_image">Imagem de compartilhamento</option><option value="ad_banner">Banner publicitário</option></select></label><label>Descrição<input name="alt_text"></label><label>Ordem<input type="number" name="display_order" value="0"></label><label>Arquivo<input type="file" name="file" required></label></div><button class="button primary" type="submit">Enviar ativo</button></form></section><section class="panel"><h2>Regulamento <?= $locked?'bloqueado após início':'editável' ?></h2><form method="post" action="/admin/tournaments/<?=$tournament['id']?>/rules"><input type="hidden" name="_csrf" value="<?=View::e(Security::csrfToken())?>"><label>Configuração JSON<textarea name="settings_json" rows="18"><?=View::e(json_encode($settings,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></textarea></label><label>Justificativa<input name="reason" required></label><?php if($locked): ?><label><input type="checkbox" name="authorize_after_start" value="1"> Autorizar nova versão após início</label><?php endif; ?><button class="button primary" type="submit">Salvar versão</button><button class="button" type="submit" name="preset" value="1">Aplicar preset Copa Brasil</button></form></section><section class="panel"><h2>Histórico</h2><div class="table-wrap"><table><thead><tr><th>Versão</th><th>Motivo</th><th>Responsável</th><th>Data</th><th>Ativa</th></tr></thead><tbody><?php foreach($versions as $v): ?><tr><td><?=$v['version_number']?></td><td><?=View::e($v['change_reason'])?></td><td><?=View::e($v['user_name']??'Sistema')?></td><td><?=View::e($v['created_at'])?></td><td><?=$v['is_active']?'Sim':'Não'?></td></tr><?php endforeach; ?></tbody></table></div></section></main>
